{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 청년 기본 조례상 청년 지원 신청 시 의무복무로 인한 나이 제한 3세 연장 적용 여부",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "의무복무 제대군인이 청년정책에 참여하려는 경우 시장은 복무기간을 고려하여 최대 세 살의 범위에서 참여 대상자 연령 상한을 연장하여 적용할 수 있습니다. 이는 무조건 3세를 늘려 주는 것이 아니라, 복무기간을 고려한 재량 적용이며 연장 범위도 최대 세 살까지입니다. 따라서 1년 반 복무했다고 해서 자동으로 3세가 연장되는 것은 아닙니다.",
          "b_ids": "청년:제24조"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
